// AUTO-GENERATED BY silc — DO NOT EDIT
/** F1 settings / save overlay. */

import type { Resources } from "../kernel/resources.ts";
import type { GameSystem } from "../kernel/systems.ts";
import type { World } from "../kernel/world.ts";
import type { AttributeState } from "../framework/spawn.ts";
import type { Possession } from "../framework/mode.ts";

export function createOverlaySystem(
  world: World,
  resources: Resources,
  possession: Possession,
): GameSystem {
  let root: HTMLDivElement | null = null;
  let visible = false;
  let status = "";

  return {
    name: "overlay",
    order: 80,
    init() {
      root = document.createElement("div");
      root.id = "silc-game-overlay";
      root.style.cssText =
        "display:none;position:fixed;inset:12px auto auto 12px;z-index:20;min-width:280px;padding:12px 14px;background:rgba(8,12,18,0.88);color:#e8eef7;font:13px/1.45 ui-monospace,SFMono-Regular,Menlo,monospace;border:1px solid rgba(255,255,255,0.12);border-radius:8px;";
      document.body.appendChild(root);

      window.addEventListener("keydown", (e) => {
        const toggle = resources.manifest.overlay?.toggle || "F1";
        if (e.key === toggle || e.code === toggle) {
          visible = !visible;
          if (root) root.style.display = visible ? "block" : "none";
          if (visible) render();
        }
        if (visible && e.key === "F5") {
          e.preventDefault();
          void doSave().then(render);
        }
        if (visible && e.key === "F9") {
          e.preventDefault();
          void doLoad().then(render);
        }
      });
    },
    update() {
      if (visible) render();
    },
    dispose() {
      root?.remove();
      root = null;
    },
  };

  function render() {
    if (!root) return;
    const pawnId = possession.pawnId;
    const attrs =
      pawnId != null ? world.getComponent<AttributeState[]>("attributes", pawnId) ?? [] : [];
    const attrLines = attrs.map((a) => `${a.name}=${a.value.toFixed(1)}`).join("  ") || "(none)";
    const pos = pawnId != null ? world.worldPosition(pawnId) : { x: 0, y: 0, z: 0 };
    const vel =
      pawnId != null
        ? world.getComponent<{ vx: number; vy: number; vz: number }>("velocity", pawnId)
        : null;
    const grounded =
      pawnId != null ? world.getComponent<{ value: boolean }>("grounded", pawnId)?.value : false;
    root.innerHTML = `
      <div><strong>${resources.manifest.title}</strong> · mode ${possession.modeId}</div>
      <div>score ${possession.score} · last ${possession.lastAbility ?? "—"}</div>
      <div>pos ${pos.x.toFixed(2)} ${pos.y.toFixed(2)} ${pos.z.toFixed(2)} · ${
        grounded ? "grounded" : "airborne"
      }</div>
      <div>vel ${(vel?.vx ?? 0).toFixed(2)} ${(vel?.vy ?? 0).toFixed(2)} ${(vel?.vz ?? 0).toFixed(2)}</div>
      <div>attrs ${attrLines}</div>
      <div style="margin-top:8px;opacity:.85">F5 save · F9 load · ${resources.manifest.overlay.toggle} toggle</div>
      <div style="opacity:.7">${status}</div>
    `;
  }

  async function doSave() {
    const pawnId = possession.pawnId;
    const attrs =
      pawnId != null ? world.getComponent<AttributeState[]>("attributes", pawnId) ?? [] : [];
    const pos = pawnId != null ? world.worldPosition(pawnId) : { x: 0, y: 0, z: 0 };
    const res = await resources.save.put({
      slot: "autosave",
      modeId: possession.modeId,
      score: possession.score,
      revision: Date.now(),
      pawn: pos,
      attributes: attrs,
    });
    status = res.ok ? "saved autosave" : "save failed";
    void resources.telemetry.event("save", { slot: "autosave", score: possession.score });
  }

  async function doLoad() {
    const data = await resources.save.get("autosave");
    if (!data) {
      status = "no autosave";
      return;
    }
    possession.score = Number(data.score ?? possession.score);
    const pawnId = possession.pawnId;
    if (pawnId != null && data.pawn && typeof data.pawn === "object") {
      const p = data.pawn as { x?: number; y?: number; z?: number };
      world.setTransform(pawnId, {
        x: p.x ?? 0,
        y: p.y ?? 0,
        z: p.z ?? 0,
      });
    }
    if (pawnId != null && Array.isArray(data.attributes)) {
      world.addComponent("attributes", pawnId, data.attributes as AttributeState[]);
    }
    status = "loaded autosave";
  }
}
